// 1. Поиск входных данных (проверяем несколько возможных путей n8n)
const item = $input.first().json;
const inputString = item.text || 
                   (item.parts && item.parts[0] && item.parts[0].text) || 
                   (item.content && item.content.parts && item.content.parts[0].text) || 
                   "";

// 2. Контроль ошибок: если вход пустой, выводим сообщение об ошибке вместо пустого списка
if (!inputString || inputString.length < 10) {
    return [{ json: { error: "Текст не найден. Проверьте, что в предыдущем узле данные называются 'text' или лежат в 'parts'." } }];
}

// 3. Разрезаем текст по разделителю "---"
const rawFragments = inputString.split(/\n?\s*---\s*\n?/);
const result = [];

// 4. Регулярное выражение (с поддержкой всех видов тире и пробелов)
const regex = /\[(\d{1,2}:\d{2})\]\s*[–—\-]\s*\[(\d{1,2}:\d{2})\]\s*([\s\S]+)/;

for (const fragment of rawFragments) {
    const trimmed = fragment.trim();
    if (!trimmed) continue;

    const match = trimmed.match(regex);
    if (match) {
        result.push({
            json: {
                start: match[1],      // Время начала
                end: match[2],        // Время конца
                content: match[3].trim() // Чистый текст фрагмента
            }
        });
    }
}

// 5. Контроль ошибок на выходе
if (result.length === 0) {
    return [{ json: { error: "Таймкоды не распознаны. Проверьте формат: [00:00] – [00:00]" } }];
}

return result;
